CREATE TABLE departments(id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE users(id text PRIMARY KEY, username text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','moderator','admin')), department_id text REFERENCES departments(id), active boolean NOT NULL DEFAULT true, must_reset boolean NOT NULL DEFAULT false, bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE password_resets(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE invitations(id text PRIMARY KEY, code_hash text NOT NULL UNIQUE, label text NOT NULL, department_id text REFERENCES departments(id), max_uses int NOT NULL CHECK(max_uses>0), used_count int NOT NULL DEFAULT 0 CHECK(used_count>=0 AND used_count<=max_uses), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitation_uses(invitation_id text REFERENCES invitations(id), user_id text REFERENCES users(id), used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(invitation_id,user_id));
CREATE TABLE categories(id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE tags(id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE tool_names(id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE moderator_scopes(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, department_id text REFERENCES departments(id), category_id text REFERENCES categories(id), CHECK(department_id IS NOT NULL OR category_id IS NOT NULL));
CREATE TABLE contents(id text PRIMARY KEY, author_id text NOT NULL REFERENCES users(id), type text NOT NULL CHECK(type IN ('experience','project','skill','prompt')), category_id text NOT NULL REFERENCES categories(id), visibility text NOT NULL DEFAULT 'company' CHECK(visibility IN ('company','departments')), state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','withdrawn','deleted')), published_revision_id text, latest_revision_id text, featured boolean NOT NULL DEFAULT false, pinned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE content_departments(content_id text REFERENCES contents(id) ON DELETE CASCADE, department_id text REFERENCES departments(id), PRIMARY KEY(content_id,department_id));
CREATE TABLE revisions(id text PRIMARY KEY, content_id text NOT NULL REFERENCES contents(id), number int NOT NULL, data jsonb NOT NULL, digest text NOT NULL, status text NOT NULL CHECK(status IN ('draft','queued','review','rejected','approved')), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(content_id,number));
ALTER TABLE contents ADD CONSTRAINT published_revision_fk FOREIGN KEY(published_revision_id) REFERENCES revisions(id);
ALTER TABLE contents ADD CONSTRAINT latest_revision_fk FOREIGN KEY(latest_revision_id) REFERENCES revisions(id);
CREATE TABLE resource_versions(id text PRIMARY KEY, content_id text NOT NULL REFERENCES contents(id), revision_id text NOT NULL UNIQUE REFERENCES revisions(id), version text NOT NULL, changelog text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments(id text PRIMARY KEY, content_id text NOT NULL REFERENCES contents(id), owner_id text NOT NULL REFERENCES users(id), original_name text NOT NULL, storage_key text NOT NULL UNIQUE, mime text NOT NULL, size bigint NOT NULL, kind text NOT NULL CHECK(kind IN ('image','resource')), scan_status text NOT NULL CHECK(scan_status IN ('clean','review','blocked')), scan_reason text NOT NULL DEFAULT '', extracted_text text NOT NULL DEFAULT '', deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revision_attachments(revision_id text REFERENCES revisions(id), attachment_id text REFERENCES attachments(id), PRIMARY KEY(revision_id,attachment_id));
CREATE TABLE likes(content_id text REFERENCES contents(id), user_id text REFERENCES users(id), active boolean NOT NULL DEFAULT true, first_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(content_id,user_id));
CREATE TABLE bookmarks(content_id text REFERENCES contents(id), user_id text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(content_id,user_id));
CREATE TABLE comments(id text PRIMARY KEY, content_id text NOT NULL REFERENCES contents(id), author_id text NOT NULL REFERENCES users(id), parent_id text REFERENCES comments(id), body text NOT NULL, digest text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','review','rejected','approved','deleted')), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE download_events(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), content_id text NOT NULL REFERENCES contents(id), attachment_id text NOT NULL REFERENCES attachments(id), revision_id text NOT NULL REFERENCES revisions(id), counted boolean NOT NULL, day date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX downloads_daily ON download_events(user_id,content_id,day) WHERE counted;
CREATE TABLE external_events(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), content_id text NOT NULL REFERENCES contents(id), field text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), content_id text REFERENCES contents(id), kind text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE banners(id text PRIMARY KEY, content_id text REFERENCES contents(id), title text NOT NULL, description text NOT NULL DEFAULT '', external_url text, image_id text REFERENCES attachments(id), position int NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, starts_at timestamptz, ends_at timestamptz, CHECK(content_id IS NOT NULL OR external_url IS NOT NULL));
CREATE TABLE moderation_jobs(id text PRIMARY KEY, revision_id text REFERENCES revisions(id), comment_id text REFERENCES comments(id), digest text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','review','failed','done')), attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK((revision_id IS NULL) <> (comment_id IS NULL)));
CREATE UNIQUE INDEX jobs_revision ON moderation_jobs(revision_id) WHERE revision_id IS NOT NULL;
CREATE UNIQUE INDEX jobs_comment ON moderation_jobs(comment_id) WHERE comment_id IS NOT NULL;
CREATE TABLE moderation_records(id text PRIMARY KEY, job_id text NOT NULL REFERENCES moderation_jobs(id), decision text NOT NULL, categories jsonb NOT NULL DEFAULT '[]', reason text NOT NULL, provider text NOT NULL, actor_id text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_rules(id text PRIMARY KEY, name text NOT NULL, phrase text NOT NULL CHECK(length(phrase)>=4), reason text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE reports(id text PRIMARY KEY, content_id text NOT NULL REFERENCES contents(id), comment_id text REFERENCES comments(id), reporter_id text NOT NULL REFERENCES users(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), resolution text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE audit_logs(id text PRIMARY KEY, actor_id text REFERENCES users(id), action text NOT NULL, target text NOT NULL, result text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX content_browse ON contents(state,published_at DESC);
CREATE INDEX content_author ON contents(author_id,state);
CREATE INDEX content_department ON content_departments(department_id,content_id);
CREATE INDEX revisions_content ON revisions(content_id,number DESC);
CREATE INDEX comments_content ON comments(content_id,status,created_at);
CREATE INDEX jobs_queue ON moderation_jobs(status,available_at,locked_until);
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX downloads_ranking ON download_events(created_at,content_id) WHERE counted;
CREATE INDEX likes_ranking ON likes(first_at,content_id) WHERE active;
CREATE INDEX attachments_owner ON attachments(owner_id) WHERE NOT deleted;
